          const name = String(val('name') || '').trim().toLowerCase(); const type = val('type');
          if (!/^[a-z][a-z0-9_]*$/.test(name)) { ctx.toast('400: field names are lower-case letters, digits and _.', 'danger'); return; }
          if (['id', 'state', 'label', 'version', 'createdAt', 'updatedAt', 'createdat', 'updatedat'].includes(name)) { ctx.toast('400: ' + esc(name) + ' is reserved for record properties.', 'danger'); return; }
          if (idx == null && ent.fields.some((x) => x.name === name)) { ctx.toast('400: a field named ' + esc(name) + ' exists.', 'danger'); return; }
          const nf = { name, title: val('title') || undefined, description: val('description') || undefined, type, required: !!val('required'), indexed: !!val('indexed'), unique: !!val('unique') };
          if (type === 'string') { if (val('maxLength')) nf.maxLength = +val('maxLength'); if (val('pattern')) nf.pattern = val('pattern'); if (val('multiline')) nf.multiline = true; if ((nf.indexed || nf.unique) && nf.maxLength > 255) { ctx.toast('400: an indexed or unique string is at most 255 characters.', 'danger'); return; } }
