          if (type === 'json') nf.maxBytes = +val('maxBytes') || 16384;
          if (type === 'formula') { nf.expression = val('expression'); const p = checkFormula(nf.expression, ent); if (p) { ctx.toast('422: ' + esc(p), 'danger'); return; } nf.indexed = false; nf.unique = false; }
          if (type === 'ai') { nf.profile = val('profile'); nf.prompt = val('prompt'); nf.maxLength = +val('maxLength') || 400; nf.indexed = false; nf.unique = false; }
